@startuml

class Gym {
  + ComputeMonthlyBalance(month: int, year: int): double
  + ComputeYearlyBalance(year: int): double
  + SendArrearsReminder(): void
  + SendMedicalCheckReminder(): void
}

class Customer {
  + Name : string
  + Surname : string
  + Age : int
  + Address : string
  + Profession : string
  + SubscriptionType : string
}

class Subscription {
  + Type : string
}

class Service {
  + Name : string
  + IsBaseService : boolean
}

class WorkoutPlan {
  + Exercises : string
  + Repetitions : int
  + Frequency : int
}

class MedicalStaff {
  + Name : string
}

class MedicalCheck {
  + Date : date
  + Weight : float
  + BodyFat : float
  + Electrocardiogram : string
  + RestingHeartbeat : int
  + StressHeartbeat : int
}

Gym "1" -- "*" Customer
Gym "1" -- "*" Subscription
Gym "1" -- "*" Service
Gym "1" -- "*" MedicalStaff

Customer "1" -- "1" Subscription
Customer "1" -- "0..1" WorkoutPlan
Customer "0..*" -- "0..*" Service
Customer "0..*" -- "0..*" MedicalStaff : requests

WorkoutPlan "1" -- "0..*" Service : includes

MedicalStaff "1" -- "*" MedicalCheck : performs
MedicalCheck "1" -- "1" Customer : belongs to

@enduml

